using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Structure;

var doc = Document;
var symbol  = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_StructuralFraming).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().First();
var level   = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).First();
var tagType = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_StructuralFramingTags).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().First();

ElementId beamId = null, tagId = null;
string viewName = null;
Connector.WithTransaction(doc, () => {
    if (!symbol.IsActive) symbol.Activate();
    if (!tagType.IsActive) tagType.Activate();
    var beam = doc.Create.NewFamilyInstance(Line.CreateBound(new XYZ(0, 25, 0), new XYZ(20, 25, 0)), symbol, level, StructuralType.Beam);
    beamId = beam.Id;
    doc.Regenerate();

    // a plan at the beam's level where structural framing shows -- prefer a structural (Engineering) plan
    var view = new FilteredElementCollector(doc).OfClass(typeof(ViewPlan)).Cast<ViewPlan>()
                 .FirstOrDefault(v => !v.IsTemplate && v.ViewType == ViewType.EngineeringPlan && v.GenLevel != null && v.GenLevel.Id == level.Id)
             ?? new FilteredElementCollector(doc).OfClass(typeof(ViewPlan)).Cast<ViewPlan>()
                 .First(v => !v.IsTemplate && v.ViewType == ViewType.FloorPlan && v.GenLevel != null && v.GenLevel.Id == level.Id);
    viewName = view.Name;

    var tag = IndependentTag.Create(doc, tagType.Id, view.Id, new Reference(beam), false, TagOrientation.Horizontal, new XYZ(10, 27, 0));
    tagId = tag.Id;
});

var t = (IndependentTag)doc.GetElement(tagId);
return new { beamId = beamId.ToString(), tagId = tagId.ToString(), tagType = tagType.Name, view = viewName, taggedCount = t.GetTaggedLocalElementIds().Count };
